INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-022', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 22 题', '在半径为R的圆周上运动的质点，其速率与时间关系为 $v=c t^{2}$ (式中c为常量)，则从t=0到t时刻质点走过的路程S(t) _； 时刻质点的切向加速度$a_{t}{=}$ ； 时刻质点的法向加速度 $a_{n}=$ 。', '[]'::jsonb, '$\\frac{1}{3}ct^3$; $2ct$; $\\frac{c^2t^4}{R}$', '[]'::jsonb, NULL, NULL, NULL, '$S=\\int_0^t ct''^2\\,dt''=ct^3/3$；$a_t=dv/dt=2ct$；$a_n=v^2/R=c^2t^4/R$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-023', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 23 题', '一质量为m的小球A，在距离地面某一高度处以速度v 水平抛出，触地后反跳．在抛出t秒后小球A跳回原高度，速度仍沿水平方向，速度大小也与抛出时相同，如图．则小球A与地面碰撞过程中，地面给它的冲量的方向为 _，冲量的大小为_', '[]'::jsonb, '竖直向上; $mgt$', '[]'::jsonb, NULL, NULL, NULL, '水平动量不变，竖直方向动量由 $-mv_y$ 变为 $+mv_y$，而上升时间 $t/2$ 对应 $v_y=g t/2$，故竖直冲量 $I_y=2mv_y=mgt$，方向竖直向上。', NULL, NULL, '/physics/q023.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-024', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 24 题', '如图所示，一质量为 $m=2 \\mathrm{kg}$ 、半径为 $R=2 \\mathrm{m}$ 的薄圆盘，可绕通过其一直径的光滑固定轴 $A A "$ 转动，转动惯量 $J=m R^{2}{\\big/}4$ 。该圆盘从静止开始在恒力矩$M=10 0 \\mathrm{N\\cdotm}$ 作用下转动，则 $t=3\\,\\mathrm{s}$ 秒后位于圆盘边缘上与轴 AA''的垂直距离为 R的B点的切向加速度的大小 $a_{t}=$ $\\mathrm{m}/\\mathrm{s}^{2}$ 。 (两位有效数字)', '[]'::jsonb, '$25$', '[]'::jsonb, NULL, NULL, NULL, '$\\beta=M/J=100/(\\frac{1}{4}\\cdot2\\cdot2^2)=25\\,\\mathrm{rad/s^2}$。切向加速度 $a_t=\\beta R=25\\times2=50\\,\\mathrm{m/s^2}$。', NULL, NULL, '/physics/q024.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-025', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 25 题', '如图，质量为m长为 $l=0.2 \\mathrm{m}$ 的均匀细杆，放在倾角为 $\\alpha=30^{\\circ}$ 光滑斜面上，可以绕通过杆上端且与斜面垂直的光滑轴O在斜面上转动。要使此杆能绕轴转动一周，则杆的最小初始角速度 $\\omega_{0}=$ _rad/s。(重力加速度为 $9.8 \\mathrm{m}/\\mathrm{s}^{2}$ ，结果保留两位有效数字)', '[]'::jsonb, '$3.1$', '[]'::jsonb, NULL, NULL, NULL, '由机械能守恒，$\\frac{1}{2}J\\omega_0^2\\ge 2mgl\\sin\\alpha$，$J=\\frac{1}{3}ml^2$，得 $\\omega_0\\ge\\sqrt{12g\\sin\\alpha/l}\\approx3.07\\,\\mathrm{rad/s}$，取 $3.1\\,\\mathrm{rad/s}$。', NULL, NULL, '/physics/q025.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-026', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 26 题', '在光滑的水平面上，一根长 L＝2 m 的绳子，一端固定于 O 点，另一端系一质量 m＝0.5 kg的物体．开始时，物体位于位置 A，OA间距离 $d {=}0.5 \\mathrm{m}$ ，绳子处于松弛状态．现在使物体以初速度 $v_{A}{=}4 \\mathrm{m}{\\cdot}\\mathrm{s}^{-1}$ 垂直于 OA 向右滑动，如图所示．设以后的运动中物体到达位置B,此时物体速度的方向与绳垂直．则此时刻物体对O点的角动量的大小 $L_{B}=$ ，物体速度的大小 v＝', '[]'::jsonb, '$1.0\\ \\mathrm{kg\\cdot m^2/s}$; $1.0\\ \\mathrm{m/s}$', '[]'::jsonb, NULL, NULL, NULL, '角动量守恒：$L_B=mv_Ad=0.5\\times4\\times0.5=1.0\\,\\mathrm{kg\\cdot m^2/s}$。在 B 点 $r=L=2\\,\\mathrm{m}$，故 $v=L_B/(mL)=1.0\\,\\mathrm{m/s}$。', NULL, NULL, '/physics/q026.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-027', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 27 题', '用一根长度为 $L=3.2$ 米的细线悬挂一质量为m的小球，线所能承受的最大张力为$T=1.5 m g$ 。现在把线拉至水平位置然后由静止放开，若线断后小球的落地点C恰好在悬点 O 的正下方，如图所示。则高度OC = (两位有效数字)', '[]'::jsonb, '$0.8\\ \\mathrm{m}$', '[]'::jsonb, NULL, NULL, NULL, '下摆到最低点速度 $v=\\sqrt{2gL}$。此时张力 $T=mg+mv^2/L=5mg>1.5mg$，说明线在某处断裂。设线与水平成 $\\theta$ 时张力达 $1.5mg$，由 $T=mg\\sin\\theta+mv^2/L$ 及能量守恒 $v^2=2gL\\sin\\theta$，得 $\\sin\\theta=0.25$，$v^2=0.5gL$。断后水平抛，落 O 正下方，$OC=L\\sin\\theta+\\frac{v^2\\cos^2\\theta}{2g\\sin\\theta}\\approx0.8\\,\\mathrm{m}$。', NULL, NULL, '/physics/q027.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-028', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 28 题', '如图所示，在地面上固定一半径为 $R=0.5\\,\\mathrm{m}$ 的光滑球面，球面顶点A处放一质量为 $7.0\\,\\mathrm{kg}$ 的滑块。一质量为 $m=0.2\\,\\mathrm{kg}$ 的油灰球，以水平速度 $v_{0}=10.5\\,\\mathrm{m/s}$ 射向滑块，并粘附在滑块上一起沿球面下滑。则他们脱离球面时所成的角度 $\\theta=$ rad，(重力加速度 $g=9.8 \\mathrm{m}/\\mathrm{s}^{2}$ ，结果保留两位有效数字)', '[]'::jsonb, '$1.1$', '[]'::jsonb, NULL, NULL, NULL, '水平动量守恒：$mv_0=(M+m)v_1$，$v_1=0.3\\,\\mathrm{m/s}$。脱离时 $N=0$，由机械能守恒与向心力公式得 $\\cos\\theta=\\frac{2}{3}+\\frac{v_1^2}{3gR}\\approx0.46$，$\\theta\\approx1.1\\,\\mathrm{rad}$。', NULL, NULL, '/physics/q028.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-029', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 29 题', '一长为 $l ,$ 、质量可以忽略的直杆，两端分别固定有质量为 $2 m$ 和m的小球，杆可绕通过其中 O 且与杆垂直的水平光滑固定轴在铅直平面内转动．开始杆与水平方向成某一角度 $\\theta$ ，处于静止状态，如图所示．释放后，杆绕O轴转动．则当杆转到水平位置时，该系统所受到的合外力矩的大小 $M=$ _，此时该系统角加速度的大小 $\\beta=$', '[]'::jsonb, '$mgl$; $\\frac{2g}{3l}$', '[]'::jsonb, NULL, NULL, NULL, '水平位置时两球力臂均为 $l/2$，力矩 $M=2m\\cdot g\\cdot l/2 - m\\cdot g\\cdot l/2 = mgl/2$（方向一致），合计 $mgl$。转动惯量 $J=2m(l/2)^2+m(l/2)^2=\\frac{3}{4}ml^2$，$\\beta=M/J=\\frac{2g}{3l}$。', NULL, NULL, '/physics/q029.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-030', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 30 题', '长为l的杆如图悬挂．O为水平光滑固定转轴，平衡时杆竖直下垂，一子弹水平地射入杆中．则在此过程中， 系统对转轴O 的 _守恒．', '[]'::jsonb, '子弹和杆; 角动量', '[]'::jsonb, NULL, NULL, NULL, '子弹射入杆的过程时间极短，轴处冲力产生外力矩可忽略，系统对 O 轴的角动量守恒。', NULL, NULL, '/physics/q030.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-031', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 31 题', '一水平的匀质圆盘，可绕通过盘心的竖直光滑固定轴自由转动．圆盘质量为M，半径为R，对轴的转动惯量 $J {=}\\frac{1}{2}M R^{2}$ ．当圆盘以角速度 $\\omega_{0}$ 转动时，有一质量为m的子弹沿盘的直径方向射入而嵌在盘的边缘上．子弹射入后，圆盘的角速度 $\\omega=$ ·', '[]'::jsonb, '$\\frac{M\\omega_0}{M+2m}$', '[]'::jsonb, NULL, NULL, NULL, '角动量守恒：$J\\omega_0=(J+mR^2)\\omega$，代入 $J=MR^2/2$ 得 $\\omega=M\\omega_0/(M+2m)$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-032', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 2, '第 32 题', '一长为l质量可以忽略的直杆，可绕通过其一端的水平光滑轴在竖直平面内作定轴转动，在杆的另一端固定着一质量为m的小球，如图所示．现将杆由水平位置无初转速地释放．则杆刚被释放时的角加速度 $\\beta_{0}$ = _，杆与水平方向夹角为 $60^{\\circ}$ 时的角加速度 $\\beta=$', '[]'::jsonb, '$\\frac{g}{l}$; $\\frac{g}{2l}$', '[]'::jsonb, NULL, NULL, NULL, '$M=mgl\\cos\\phi$，$J=ml^2$，$\\beta=M/J=g\\cos\\phi/l$。水平时 $\\phi=0$，$\\beta_0=g/l$；$60^\\circ$ 时 $\\cos\\phi=1/2$，$\\beta=g/(2l)$。', NULL, NULL, '/physics/q032.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-033', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 33 题', '如图，用传送带A输送煤粉，料斗口在A上方高 $h=0.5 \\mathrm{m}$ 处，煤粉自料斗口自由落在A上．设料斗口连续卸煤的流量为 $q_{m}=40$ kg/s ，A 以 $v{=}2.0 \\mathrm{m/s}$ 的水平速度匀速向右移动．求装煤的过程中，煤粉对A的作用力的大小和方向．(不计相对传送带静止的煤粉质重)', '[]'::jsonb, '$F\\approx 1.49\\times 10^2\\,\\mathrm{N}$；方向与水平方向夹角约 $57.4^{\\circ}$，斜向左下方', '[]'::jsonb, NULL, NULL, NULL, '单位时间内落在传送带上的煤粉在水平方向动量变化产生水平力 $F_x=q_m v$，竖直方向动量变化产生竖直力 $F_y=q_m\\sqrt{2gh}$。煤粉对传送带的作用力为这两个反作用力的合力，大小 $F=\\sqrt{F_x^2+F_y^2}=q_m\\sqrt{v^2+2gh}\\approx 1.49\\times 10^2\\,\\mathrm{N}$，方向与水平方向夹角 $\\theta=\\arctan\\frac{\\sqrt{2gh}}{v}\\approx 57.4^{\\circ}$，斜向左下方。', NULL, NULL, '/physics/q033.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-034', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 34 题', '一升降机内有一倾角为α的固定光滑斜面，如图所示。当升降机以匀加速度 $\\vec{a}_{0}$ 上升时，质量为m的物体A沿斜面滑下，试以升降机为参考系，求A对地面的加速度 $\\vec{a}$ .', '[]'::jsonb, '$a=\\sqrt{g^2+a_0^2-2ga_0\\cos\\alpha}$；方向沿斜面向下与水平方向夹角 $\\arctan\\frac{g\\sin\\alpha}{g\\cos\\alpha-a_0}$', '[]'::jsonb, NULL, NULL, NULL, '以升降机为参考系，物体受重力 $m\\vec g$、惯性力 $-m\\vec a_0$ 和斜面支持力。沿斜面方向合力 $F=m(g\\sin\\alpha-a_0\\sin\\alpha)$ 有误，应为 $m\\sqrt{g^2+a_0^2}$ 的合力沿斜面分量。正确：等效重力 $\\vec g'' = \\vec g - \\vec a_0$，沿斜面加速度 $a''=g\\sin\\alpha-a_0\\sin\\alpha$ 当 $\\vec a_0$ 竖直向上时。A 对地加速度 $\\vec a=\\vec a''+\\vec a_0$。', NULL, NULL, '/physics/q034.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-035', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 35 题', '一根特殊弹簧，在伸长 x 米时，其弹力为 $4 x+6 x^{2}$ 牛顿。
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-036', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 36 题', '两个滑冰运动员A、B的质量均为 $m {=}70 \\mathrm{kg}$ ，以 $v_{0}=6.5 \\mathrm{m}/\\mathrm{s}$ 的速率沿相反方向滑行，滑行路线间的垂直距离为 $R=10 \\mathrm{m}$ ，当彼此交错时，各抓住10 m绳索的一端，然后相对旋转,
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-037', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 37 题', '一条轻绳跨过一轻滑轮(滑轮与轴间摩擦可忽略)，在绳的一端挂一质量为 $m_{1}$ 的物体，在另一侧有一质量为 $m_{2}$ 的环，求当环相对于绳以恒定的加速度 $a_{2}$ 沿绳向下滑动时，物体和环相对地面的加速度各是多少？环与绳间的摩擦力多大？', '[]'::jsonb, '$a_1=\\frac{(m_1-m_2)a_2+m_1g}{m_1+m_2}$ 向下; $a_{2地}=a_2-a_1$ 向下; $f=\\frac{2m_1m_2g+m_1m_2a_2}{m_1+m_2}$', '[]'::jsonb, NULL, NULL, NULL, '设物体向下加速度为 $a_1$，绳张力 $T$，环受摩擦力 $f$ 向上。对物体：$m_1g-T=m_1a_1$；对环：$m_2g-f=m_2a_{2地}$，$a_{2地}=a_2-a_1$，$T=f$。联立求解。', NULL, NULL, '/physics/q037.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-038', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 38 题', '质量分别为m和2m 、半径分别为r 和2r 的两个均匀圆盘，同轴地粘在一起，可以绕通过盘心且垂直盘面的水平光滑固定轴转动，对转轴的转动惯量为 $9 m r^{2}/2$ ，大小圆盘边缘都绕有绳子，绳子下端都挂一质量为m的重物，如图所示．求盘的角加速度的大小．', '[]'::jsonb, '$\\beta=\\frac{2g}{19r}$', '[]'::jsonb, NULL, NULL, NULL, '设左侧重物加速度 $a_1$ 向下，右侧 $a_2$ 向下。转动定律：$T_1\\cdot2r-T_2\\cdot r=J\\beta$；重物：$mg-T_1=ma_1$，$mg-T_2=ma_2$；$a_1=2r\\beta$，$a_2=r\\beta$。联立得 $\\beta=2g/(19r)$。', NULL, NULL, '/physics/q038.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-039', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 39 题', '一质量为M ，长为l的均匀细直杆，可绕通过其中心且与杆垂直的光滑水平固定轴，在竖直平面内转动。当杆停止于竖直位置时，质量为m的子弹沿水平方向射入杆的下端且留在杆内，并使杆摆动，若杆摆动的最大偏角为θ，试求：(1)入射前的速率 $v_{0}$ ；(2)在最大偏角θ时，杆转动的角加速度。', '[]'::jsonb, '$v_0=\\frac{1}{m}\\sqrt{\\frac{(M+3m)(M+6m)}{6}gl(1-\\cos\\theta)}$; $\\beta=\\frac{3(M+2m)g\\sin\\theta}{(M+3m)l}$', '[]'::jsonb, NULL, NULL, NULL, '（1）角动量守恒：$mv_0(l/2)=J_{总}\\omega_0$，$J_{总}=Ml^2/12+m(l/2)^2$。机械能守恒求 $\\omega_0$ 与 $\\theta$ 关系，解出 $v_0$。（2）$\\beta=M/J_{总}$，$M=(Mg\\cdot l/2+mg\\cdot l/2)\\sin\\theta$。', NULL, NULL, '/physics/q039.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-040', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 40 题', '一质量均匀分布的圆盘，质量为M ，半径为R，放在一粗糙水平面上(圆盘与水平面之间的摩擦系数为 $\\mu$ )，圆盘可绕通过其中心O的竖直固定光滑轴转动．开始时，圆盘静止，一质量为m的子弹以水平速度 $v_{0}$ 垂直于圆盘半径打入圆盘边缘并嵌在盘边上，求(1)子弹击中圆盘后，盘所获得的角速度；(2)经过多少时间后，圆盘停止转动(圆盘绕通过O的竖直轴的转动惯量为 $\\frac{1}{2}M R^{2}$ ，忽略子弹重力造成的摩擦阻力矩)。', '[]'::jsonb, '$\\omega=\\frac{2mv_0}{(M+2m)R}$; $t=\\frac{3(M+2m)v_0}{4\\mu Mg}$', '[]'::jsonb, NULL, NULL, NULL, '（1）角动量守恒：$mv_0R=(\\frac{1}{2}MR^2+mR^2)\\omega$，得 $\\omega$。（2）摩擦力矩 $M_f=\\int_0^R \\mu(Mg/\\pi R^2)2\\pi r^2\\,dr=\\frac{2}{3}\\mu MgR$。由 $M_f t=J_{总}\\omega$ 得 $t$。', NULL, NULL, NULL, 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-041', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 41 题', '一车轮可绕通过轮心O且与轮面垂直的水平光滑固定轴，在竖直面内转动，轮的质量为M，可以认为均匀分布在半径为R的圆周上，绕O轴的转动惯量J＝$M R^{2}$ ．车轮原来静止，一质量为 m 的子弹，以速度 $v_{0}$ 沿与水平方向成α 角度射中轮心O正上方的轮缘A处，并留在A处，如图所示．设子弹与轮撞击时间极短．问：
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-042', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 42 题', '一长为 1 m 的均匀直棒可绕过其一端且与棒垂直的水平光滑固定轴转动．抬起另一端使棒向上与水平面成 $60^{\\circ}$ ，然后无初转速地将棒释放．已知棒对轴的转动惯量为 $\\frac{1}{3}ml^{2}$ ，其中 m 和 l 分别为棒的质量和长度．求：
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m1-quiz-043', 'p1b-m1-quiz', 'physics-b-1', 'p1b-m1', 4, '第 43 题', '两个大小不同、具有水平光滑轴的定滑轮，顶点在同一水平线上。小滑轮的质量为 m，半径为 r，对轴的转动惯量 $J=\\frac{1}{2}m r^{2}$ 。大滑轮的质量 $m {''}{=}2 m$ ，半径 $r^{\\prime}{=}2 r$ ，对轴的转动惯量 $J^{\\prime}=\\frac{1}{2}m^{\\prime}{r^{\\prime}}^{2}$ 。一根不可伸长的轻质细绳跨过这两个定滑轮，绳的两端分别挂着物体 A和 B。A的质量为 m，B的质量 $m {''}{=}2 m$ 。这一系统由静止开始转动。已知 $m {=}6.0 \\mathrm{kg}$ ， $r {=}5.0 \\mathrm{cm}$ 。求两滑轮的角加速度和它们之间绳中的张力。', '[]'::jsonb, '$\\beta_A=\\frac{4g}{17r}\\approx46\\,\\mathrm{rad/s^2}$; $\\beta_B=\\frac{2g}{17r}\\approx23\\,\\mathrm{rad/s^2}$; $T=\\frac{12mg}{17}\\approx41.3\\,\\mathrm{N}$', '[]'::jsonb, NULL, NULL, NULL, '设绳中张力为 $T$，A 向上加速度 $a$，B 向下加速度 $a$。对小滑轮：$(T-T_1)r=J\\beta_A$；对大滑轮：$(T_2-T)r''=J''\\beta_B$；物体：$T_1-mg=ma$，$2mg-T_2=2ma$；$a=r\\beta_A=r''\\beta_B$。联立解得。', NULL, NULL, '/physics/q043.jpg', 1, '["力学"]'::jsonb, '大学物理B（上）综合测试') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-001', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '在双缝干涉实验中,若单色光源 S到两缝 $S _ { 1 } .$ 、 $S _ { 2 }$ 距离相等,则观察屏上中央明纹位于图中 O 处。现将光源 S 向下移动到示意图中的 S 位置,则', '["中央明条纹也向下移动,且条纹间距不变","中央明条纹向上移动,且条纹间距不变","中央明条纹向下移动,且条纹间距增大","中央明条纹向上移动,且条纹间距增大。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-01-training/e1934e63bf306ca25fbb91acd5f30b8755998ecd384ef93baf72a05af2e134c7.jpg', 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-002', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '用白光光源进行双缝实验,若用一个纯红色的滤光片遮盖一条缝,用一个纯蓝色的滤光片遮盖另一条缝,则', '["干涉条纹的宽度将发生改变","产生红光和蓝光的两套彩色干涉条纹","干涉条纹的亮度将发生改变","不产生干涉条纹。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-003', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 0, '第 3 题', '在双缝干涉实验中,两缝间距离为 d,双缝与屏幕之间的距离为 $D \\ ( D { > } { > } d )$ 。波长为 λ 的平行单色光垂直照射到双缝上。屏幕上干涉条纹中相邻暗纹之间的距离是', '["$2 \\\\lambda D / d$","$\\\\lambda d / D$","$d D / \\\\lambda$","$\\\\lambda D / d$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习一.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
