INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-005', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '在双缝干涉实验中,双缝间距为 d,双缝到屏的距离为 D( $( D { > } { > } d )$ ,测得中央零级明纹与第五级明之间的距离为 x,则入射光的波长为C', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习一.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-006', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 2, '第 6 题', '( tk1000A000009334 ) 在 双 缝 干 涉 实 验 中 , 所 用 单 色 光 波 长 为$\\lambda = 5 6 2 . 5 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ ,双缝与观察屏的距离 $D { = } 1 . 2 \\mathrm { m }$ ,若测得屏上相邻明条纹间距为 $\\Delta x = 1 . 5 \\mathrm { m m }$ ,则双缝的间距d=', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习一.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-007', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 3, '第 7 题', '在图示的双缝干涉实验中,若用薄玻璃片(折射率 $n _ { 1 } { = } 1 . 4 )$ 覆盖缝 $S _ { 1 }$ ,用同样厚度的玻璃片(但折射率 $n _ { 2 } { = } 1 . 7 )$ )覆盖缝 $S _ { 2 } ,$ ,将使原来未放玻璃 时 屏 上 的 中 央 明 条 纹 处 O 变 为 第 五 级 明 纹 。 设 单 色 光 波 长$\\lambda = 4 8 0 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ ,求玻璃片的厚度d(可认为光线垂直穿过玻璃片)。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-01-training/ac2a9ae924f795ee24739fb2373236ebe61b531e1fb8aa2ce1c1d629f0612e8d.jpg', 1, '["计算题"]'::jsonb, '波动光学练习一.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-01-training-008', 'p1b-m2-01-training', 'physics-b-1', 'p1b-m2', 3, '第 8 题', '( js1000A000008966 ) 薄 钢 片 上 有 两 条 紧 靠 的 平 行 细 缝 , 用 波 长$\\lambda = 5 4 6 . \\mathrm { l n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ 的平面光波正入射到钢片上。屏幕距双缝的距离为$D { = } 2 . 0 0 \\mathrm { m }$ ,测得中央明条纹两侧的第五级明条纹间的距离为 $\\Delta x = 1 2 . 0 \\mathrm { m m }$ 。求两缝间的距离;
(2)从任一明条纹(记作0)向一边数到第20条明条纹,共经过多大距离？
(3)如果使光波斜入射到钢片上,条纹间距将如何改变？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习一.pdf 第8题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-001', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '如图所示,折射率为 $n _ { 2 } .$ 、厚度为 e的透明介质薄膜的上方和下方的透明介质的折射率分别为 $n _ { 1 }$ 和 $n _ { 3 }$ ,已知 $n _ { 1 } { < } n _ { 2 } { < } n _ { 3 }$ 。若用波长为 λ 的单色平行光垂直入射到该薄膜上,则从薄膜上、下两表面反射的光束① 与② 的光程差是', '["$2 \\\\mathbf { n } _ { 2 } \\\\ \\\\mathbf { e }$","$2 n , e - \\\\lambda / 2$","$2 n _ { \\\\mathrm { { > } } } e - \\\\lambda$","$2 n _ { 2 } e - \\\\lambda / \\\\left( 2 n _ { 2 } \\\\right)$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-02-training/3215a92dd2998b600310a215340499e5fda0f6b07d0cfe4f7dcbe2c71250b07f.jpg', 1, '["选择题"]'::jsonb, '波动光学练习二.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-002', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '一束波长为 λ 的单色光由空气垂直入射到折射率为 n 的透明薄膜上,透明薄膜放在空气中,要使反射光得到干涉加强,则薄膜最小的厚度为', '["λ/4","$\\\\lambda / { \\\\left( 4 n \\\\right) }$","$\\\\lambda / 2$","$\\\\lambda / { \\\\left( 2 n \\\\right) }$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["选择题"]'::jsonb, '波动光学练习二.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-003', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 3 题', '如图所示,假设有两个同相的相干点光源 $S _ { 1 }$ 和 $S _ { 2 }$ ,发出波长为 λ 的光。A 是它们连线的中垂线上的一点。若在 $S _ { 1 }$ 与 A 之间插入厚度为 e、折射率为 n 的薄玻璃片,则两光源发出的光在 A 点的相位差 $\\Delta \\phi =$ \\_。若已知 $\\lambda = 5 0 0 \\mathrm { n m }$ $n { = } 1 . 5$ ,A点恰为第四级明纹中心,则 $e = { \\mathrm { ~ \\textrm ~ { ~ ~ } ~ } } { \\mathrm { n m } } _ { \\beta }$', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-02-training/18f3b401316c99fd4c7458f1da3eb568c451ca409cc9676d726b7a5f42a599b7.jpg', 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-004', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 4 题', '一束波长为 $\\lambda = 6 0 0 \\mathrm { n m \\ : \\ : ( \\ l n m { = } 1 0 ^ { - 9 } m ) }$ 的平行单色光垂直入射到折射率为 n=1.33 的透明薄膜上,该薄膜是放在空气中的。要使反射光得到最大限度的加强,薄膜最小厚度应为 nm。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第4题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-005', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 2, '第 5 题', '波长为 λ 的平行单色光垂直照射到折射率为 n 的劈形膜上,相邻的两明纹所对应的薄膜厚度之差是 C', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习二.pdf 第5题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-006', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 3, '第 6 题', '用波长为 $5 0 0 \\mathrm { n m } ~ ( 1 \\mathrm { n m } { = } 1 0 ^ { - 9 } \\mathrm { m } )$ 的单色光垂直照射到由两块光学平玻璃构成的空气劈形膜上。在观察反射光的干涉现象中,距劈形膜棱边$l { = } 1 . 5 6 \\mathrm { c m }$ 的A处是从棱边算起的第四条暗条纹中心。求此空气劈形膜的劈尖角θ;
(2)改用 600nm 的单色光垂直照射到此劈尖上仍观察反射光的干涉条纹,A 处是明条纹还是暗条纹？
(3)在第(2)问的情形从棱边到A处的范围内共有几条明纹？几条暗纹？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习二.pdf 第6题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-02-training-007', 'p1b-m2-02-training', 'physics-b-1', 'p1b-m2', 3, '第 7 题', '波长 =650nm 的红光垂直照射到劈形液膜上,膜的折射率n=1.33,液面两侧是同一种媒质。观察反射光的干涉条纹。离开劈形膜棱边的第一条明条纹中心所对应的膜厚度是多少？
(2)若相邻的明条纹间距 l=6mm,上述第一条明纹中心到劈形膜棱边的距离 x 是多少？', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["计算题"]'::jsonb, '波动光学练习二.pdf 第7题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-001', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 0, '第 1 题', '在图示三种透明材料构成的牛顿环装置中,用单色光垂直照射,在反射光中看到干涉条纹,则在接触点P处形成的圆斑为', '["全明","全暗","右半部明,左半部暗","右半部暗,左半部明。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-03-training/1282d6ac8a85a1a2039fdb78cf2190437b40cf910ea71d25fe6ba4204f0dc890.jpg', 1, '["选择题"]'::jsonb, '波动光学练习三.pdf 第1题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-002', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 0, '第 2 题', '如图 a所示,一光学平板玻璃 A与待测工件 B之间形成空气劈尖,用波长 $\\lambda = 5 0 0 \\mathrm { n m } \\big ( \\mathrm { l n m } = 1 0 ^ { - 9 } \\mathrm { m } \\big )$ 的单色光垂直照射。看到的反射光的干涉条纹如图 b 所示。有些条纹弯曲部分的顶点恰好与其右边条纹的直线部分的连续相切。则工件的上表面缺陷是', '["不平处为凸起纹,最大高度为500nm","不平处为凸起纹,最大高度为250nm","不平处为凹槽,最大深度为500nm","不平处为凹槽,最大深度为250nm。"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, '/physics/training/p1b-m2-03-training/2e64a0cd21b73d61affd67eaecafc6d9291577c8e8ca2bfd26af5a2c5122efc5.jpg', 1, '["选择题"]'::jsonb, '波动光学练习三.pdf 第2题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
INSERT INTO public.questions (id, item_id, course_id, module_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source) VALUES ('q-physics-b-1-p1b-m2-03-training-003', 'p1b-m2-03-training', 'physics-b-1', 'p1b-m2', 2, '第 3 题', '一平凸透镜,凸面朝下放在一平玻璃板上。透镜刚好与玻璃板接触。波长分别为 $\\lambda _ { 1 } = 6 0 0 \\mathrm { n m }$ 和 $\\lambda _ { 2 } = 5 0 0 \\mathrm { n m }$ 的两种单色光垂直入射,观察反射光形成的牛顿环。从中心向外数的两种光的第五个明环所对应的空气膜厚度之差为 nm。', '[]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 1, '["填空题"]'::jsonb, '波动光学练习三.pdf 第3题') ON CONFLICT (id) DO UPDATE SET item_id = EXCLUDED.item_id, course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source;
